SELECT JSON_VALUE(j, '$.a') AS a, JSON_QUERY(j, '$.b') AS b, JSON_EXTRACT_SCALAR(j, '$.a') AS c, JSON_EXTRACT_ARRAY(j, '$.arr') AS d, TO_JSON_STRING(STRUCT(1 AS x)) AS e, PARSE_JSON('{"a":1}') AS f, JSON_VALUE_ARRAY(j, '$.arr') AS g, JSON_QUERY_ARRAY(j, '$.arr') AS h, JSON_TYPE(PARSE_JSON('1')) AS i, JSON_KEYS(PARSE_JSON(j)) AS k FROM (SELECT '{"a":"x","b":{"c":1},"arr":[1,2]}' AS j)
